class PaymentValidationError extends Error {
  constructor(public readonly field: string, message: string) {
    super(message);
    this.name = 'PaymentValidationError';
  }
}

class PaymentValidator {
  private static readonly CARD_NUMBER_LENGTH = 16;
  private static readonly VALID_CVV_LENGTHS = [3, 4];
  private static readonly EXPIRY_REGEX = /^(0[1-9]|1[0-2])\/\d{2}$/;

  validate(payment: PaymentDetails): void {
    this.validateCardNumber(payment.cardNumber);
    this.validateCVV(payment.cvv);
    this.validateExpiryDate(payment.expiryDate);
  }

  private validateCardNumber(cardNumber: string): void {
    if (cardNumber.length !== PaymentValidator.CARD_NUMBER_LENGTH) {
      throw new PaymentValidationError('cardNumber', `Card number must be ${PaymentValidator.CARD_NUMBER_LENGTH} digits`);
    }
  }

  private validateCVV(cvv: string): void {
    if (!PaymentValidator.VALID_CVV_LENGTHS.includes(cvv.length)) {
      throw new PaymentValidationError('cvv', `CVV must be ${PaymentValidator.VALID_CVV_LENGTHS.join(' or ')} digits`);
    }
  }

  private validateExpiryDate(expiryDate: string): void {
    if (!PaymentValidator.EXPIRY_REGEX.test(expiryDate)) {
      throw new PaymentValidationError('expiryDate', 'Expiry date must be in MM/YY format');
    }

    const expiryDateObj = this.parseExpiryDate(expiryDate);
    if (expiryDateObj < new Date()) {
      throw new PaymentValidationError('expiryDate', 'Card has expired');
    }
  }

  private parseExpiryDate(expiryDate: string): Date {
    const [month, year] = expiryDate.split('/');
    return new Date(2000 + parseInt(year, 10), parseInt(month, 10) - 1);
  }
}

