class PaymentGateway {
  constructor(
    private readonly paymentRepo: PaymentRepository,
    private readonly logger: Logger
  ) {}

  async charge(payment: PaymentDetails, amount: number): Promise<PaymentResult> {
    const lastFour = this.maskCardNumber(payment.cardNumber);

    try {
      await this.paymentRepo.recordPayment(lastFour, amount);

      this.logger.info('Payment processed successfully', { lastFour, amount });

      return {
        success: true,
        transactionId: this.generateTransactionId()
      };
    } catch (error) {
      this.logger.error('Payment processing failed', { lastFour, amount, error });

      throw new PaymentProcessingError(
        'Failed to process payment',
        error,
        this.isRetryableError(error)
      );
    }
  }
}

